// The M30 document-route vectors, generated from the TypeScript reference itself.
//
// A module rather than a section of `generate-vectors.mjs` so it has an entry point of its own.
// `parity-regen` drives the whole generator, and the whole generator currently throws before it
// reaches here for a reason that predates this item — see
// `planning/features-to-triage/M31-parity-regen-is-broken.md`. A corpus that can only be
// regenerated by a script nobody can run is a corpus that stops being checkable.
//
//   node scripts/parity/generate-document-vectors.mjs        # writes the three files
//   MCP_ROUTER_VECTORS=/tmp/x node scripts/parity/...         # writes them somewhere else

import { writeFileSync, mkdirSync, mkdtempSync, realpathSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

export function writeDocumentVectors({ write, distDir, require }) {

  // ---------------------------------------------------------------- M30 · the document route
  //
  // The route reads a package's own files, in two implementations, and the halves worth pinning are
  // the pure ones: which references a document names, whether a reference may be read, and which cap
  // a size hits. A wire comparison of two routers that agree cannot tell a shared misreading of a
  // reference from a correct one — these can.
  const documentModule = require(join(distDir, 'document.js'));

  // ---------------------------------------------------------------- image references
  //
  // The scan is hand-written on both sides because a reference may carry balanced parentheses, and
  // every case below is a way a regex or a careless port gets a DIFFERENT reference out of the same
  // document — which means a different file read and a figure that silently never arrives.
  const documentSources = [
    { id: 'plain', text: '![a](x.png)' },
    { id: 'two-on-one-line', text: '![a](x.png) and ![b](y.png)' },
    { id: 'balanced-parens', text: '![a](img/badge_(v2).png)' },
    { id: 'title-dropped', text: '![a](x.png "a caption")' },
    { id: 'title-with-parens', text: '![a](x.png "a (caption)")' },
    { id: 'bang-not-an-image', text: 'Wait! [a](x.png) is a link.' },
    { id: 'unterminated-bracket', text: '![a(x.png)' },
    { id: 'unterminated-paren', text: '![a](x.png' },
    { id: 'empty-reference', text: '![a]()' },
    { id: 'nested-brackets-in-alt', text: '![a [b] c](x.png)' },
    { id: 'wrapped-across-lines', text: '![a](x.png)\nand ![b](y.png)' },
    { id: 'blank-line-splits-runs', text: '![a](x.png)\n\n![b](y.png)' },
    { id: 'duplicate-collapses', text: '![a](x.png)\n\n![b](x.png)' },
    { id: 'fenced-is-skipped', text: '```\n![a](x.png)\n```\n\n![b](y.png)' },
    { id: 'tilde-fence-is-skipped', text: '~~~\n![a](x.png)\n~~~\n\n![b](y.png)' },
    { id: 'split-reference-joins', text: '![a](x\n.png)' },
    { id: 'leading-whitespace-trimmed', text: '   ![a](x.png)   ' },
    { id: 'crlf', text: '![a](x.png)\r\n\r\n![b](y.png)' },
    { id: 'no-images', text: 'nothing here at all' },
    { id: 'shield-row', text: '![ci](https://img.shields.io/badge/ci-passing-green) ![v](docs/v.png)' }
  ];
  // pin-class: src-export — document.imageReferences
  write('document-image-refs', {
    description: 'document.imageReferences — every reference a document names, in order (M30).',
    cases: documentSources.map(({ id, text }) => ({
      id,
      text,
      references: documentModule.imageReferences(text)
    }))
  });

  // ---------------------------------------------------------------- resolution
  //
  // The traversal boundary. The tree is declared in the vector rather than assumed, so the Swift
  // consumer builds the SAME package before it asks the same questions — a consumer that materialised
  // a different tree would be comparing two answers to two questions.
  // The root is a FIXED-NAME directory inside the scratch, not the scratch itself: the string-prefix
  // trap needs a sibling whose name a vector can spell, and `<tmp>/pkg` beside `<tmp>/pkg-evil` is
  // deterministic where `mkdtemp`'s own suffix is not.
  const docScratch = mkdtempSync(join(tmpdir(), 'mcp-router-vectors-doc-'));
  const docPkgRoot = join(docScratch, 'pkg');
  const docTree = {
    files: ['README.md', 'docs/figure.png', 'docs/deep/nested.png', 'notes.txt', 'no-extension'],
    directories: ['looks-like.png'],
    // A package shipping a symlink out of itself is the shape a downloaded archive actually takes,
    // and standardising a path alone does not see it.
    symlinks: [{ link: 'escape.png', target: '../outside.png' }],
    // The sibling that shares a string prefix with the root and is not inside it. `/pkg-evil` has
    // `/pkg` as a prefix; comparing on segments is what tells them apart.
    sibling: 'pkg-evil'
  };
  {
    const { mkdirSync: mk, symlinkSync, writeFileSync: wf } = require('node:fs');
    mk(docPkgRoot, { recursive: true });
    for (const dir of docTree.directories) mk(join(docPkgRoot, dir), { recursive: true });
    for (const f of docTree.files) {
      mk(dirname(join(docPkgRoot, f)), { recursive: true });
      wf(join(docPkgRoot, f), 'x');
    }
    wf(join(docScratch, 'outside.png'), 'x');
    mk(join(docScratch, docTree.sibling), { recursive: true });
    wf(join(docScratch, docTree.sibling, 'x.png'), 'x');
    for (const { link, target } of docTree.symlinks) symlinkSync(target, join(docPkgRoot, link));
  }
  // `mkdtemp` hands back `/var/...`, which is itself a symlink to `/private/var` on macOS, so the
  // resolved path is LONGER than the root the reference was given. Slicing the recorded relative
  // path against the unresolved root leaves a fragment of the temp directory's own name in the
  // vector — measured, not reasoned about: the first run of this generator recorded
  // `-wwDSfL/docs/figure.png`.
  const realDocPkgRoot = realpathSync(docPkgRoot);

  const documentReferences = [
    'docs/figure.png',
    'docs/deep/nested.png',
    './docs/figure.png',
    'docs/../docs/figure.png',
    'missing.png',
    'notes.txt',
    'no-extension',
    'looks-like.png',
    'figure.svg',
    '../outside.png',
    '../../etc/passwd',
    'docs/../../outside.png',
    'escape.png',
    '../pkg-evil/x.png',
    '/etc/passwd',
    '~/secrets.png',
    'https://example.com/a.png',
    'HTTPS://example.com/a.png',
    'data:image/png;base64,AAAA',
    'file:///etc/passwd',
    'javascript:alert(1)',
    '   docs/figure.png   ',
    '',
    '.',
    '..'
  ];
  // pin-class: src-export — document.resolveInPackage
  write('document-resolve', {
    description: 'document.resolveInPackage — the traversal boundary and its refusals (M30).',
    // The Swift consumer materialises this before it compares, so both sides ask of one package.
    tree: docTree,
    cases: documentReferences.map((reference, index) => {
      const outcome = documentModule.resolveInPackage(reference, docPkgRoot);
      return {
        id: `resolve-${index}`,
        reference,
        ...(outcome.ok
          ? { kind: 'readable', relative: outcome.path.slice(realDocPkgRoot.length + 1) }
          : { kind: outcome.refusal.reason, ...outcome.refusal })
      };
    })
  });
  rmSync(docScratch, { recursive: true, force: true });

  // ---------------------------------------------------------------- the transport caps
  //
  // `MarkdownLimits` caps the parse, in the app, after the bytes have crossed. These are the wire's
  // own bounds, and the order is the part a port gets wrong: an oversized image is refused on its own
  // terms and does NOT spend the shared budget, so one huge figure must not refuse every figure after
  // it for the wrong reason.
  // pin-class: src-export — document.DOCUMENT_CAPS, document.documentOverCap, document.imageCapDecisions
  const CAPS = documentModule.DOCUMENT_CAPS;
  const documentSizes = [0, 1, CAPS.documentBytes - 1, CAPS.documentBytes, CAPS.documentBytes + 1, 1 << 24];
  const imageSizeRuns = [
    { id: 'all-small', sizes: [10, 20, 30] },
    { id: 'one-at-the-image-cap', sizes: [CAPS.imageBytes] },
    { id: 'one-over-the-image-cap', sizes: [CAPS.imageBytes + 1] },
    { id: 'oversize-does-not-spend-the-budget', sizes: [CAPS.imageBytes + 1, CAPS.imageBudgetBytes, 1] },
    { id: 'budget-exactly-spent', sizes: [CAPS.imageBudgetBytes, 1] },
    { id: 'budget-exhausted-mid-run', sizes: [CAPS.imageBytes, CAPS.imageBytes, CAPS.imageBytes, CAPS.imageBytes, CAPS.imageBytes] },
    { id: 'a-later-small-one-still-fits', sizes: [CAPS.imageBudgetBytes - 1, CAPS.imageBytes, 1] },
    { id: 'empty', sizes: [] },
    { id: 'zero-sized', sizes: [0, 0, 0] }
  ];
  write('document-caps', {
    description: 'document.documentOverCap and imageCapDecisions — which cap fires, and in what order (M30).',
    caps: CAPS,
    cases: [
      ...documentSizes.map((size, index) => ({
        id: `doc-${index}`,
        kind: 'document',
        size,
        over: documentModule.documentOverCap(size)
      })),
      ...imageSizeRuns.map(({ id, sizes }) => ({
        id,
        kind: 'images',
        sizes,
        decisions: documentModule.imageCapDecisions(sizes)
      }))
    ]
  });


}

// Run directly: build the same `write` the main generator uses, and the same output directory.
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const require = createRequire(import.meta.url);
  const here = dirname(fileURLToPath(import.meta.url));
  const repoRoot = join(here, '..', '..');
  const distDir = process.env.MCP_ROUTER_DIST ?? join(repoRoot, 'dist');
  const outDir =
    process.env.MCP_ROUTER_VECTORS ?? join(repoRoot, 'app', 'Tests', 'RouterCoreTests', 'Vectors');
  mkdirSync(outDir, { recursive: true });
  const write = (name, payload) => {
    writeFileSync(join(outDir, `${name}.json`), JSON.stringify(payload, null, 2) + '\n');
    console.log(`${name}: ${payload.cases.length} cases`);
  };
  writeDocumentVectors({ write, distDir, require });
}
